import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.Aev9KvMf.js";const u=JSON.parse('{"title":"健康中国行动（2019—2030年）· 15 个行动总览","description":"《健康中国行动（2019—2030年）》15 个行动总览：官方总纲的行动清单与目标速览，链接 gov.cn 全文。","frontmatter":{"title":"健康中国行动（2019—2030年）· 15 个行动总览","issuer":"健康中国行动推进委员会","source_tier":"一级来源","version":"2019—2030","published":"2019-07","source_url":"https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm","status":"现行","tags":["权威数据","健康中国","总纲"],"type":"数据页","reviewed":false,"description":"《健康中国行动（2019—2030年）》15 个行动总览：官方总纲的行动清单与目标速览，链接 gov.cn 全文。"},"headers":[],"relativePath":"data/healthy-china-action.md","filePath":"data/healthy-china-action.md"}'),o={name:"data/healthy-china-action.md"};function h(l,t,i,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="健康中国行动-2019—2030年-·-15-个行动总览" tabindex="-1">健康中国行动（2019—2030年）· 15 个行动总览 <a class="header-anchor" href="#健康中国行动-2019—2030年-·-15-个行动总览" aria-label="Permalink to &quot;健康中国行动（2019—2030年）· 15 个行动总览&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据 gov.cn 全文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：健康中国行动推进委员会发布（<a href="https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm" target="_blank" rel="noreferrer">gov.cn 全文</a>）· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>健康中国行动是本站所有指南词条的<strong>政策总纲</strong>：15 个行动覆盖从知识普及到重大疾病防治，每个行动都有明确的政府牵头部门和量化目标。</p><h2 id="_15-个行动" tabindex="-1">15 个行动 <a class="header-anchor" href="#_15-个行动" aria-label="Permalink to &quot;15 个行动&quot;">​</a></h2><p>按主题分三页展开（每页含各行动定位与本站关联词条）：</p><ul><li><strong><a href="/SageRelay/data/hc-action-lifestyle.html">健康生活方式与基础（行动 1—6）</a></strong>：知识普及、合理膳食、全民健身、控烟、心理健康、健康环境。</li><li><strong><a href="/SageRelay/data/hc-action-people.html">重点人群（行动 7—10）</a></strong>：妇幼、中小学、职业、老年健康。</li><li><strong><a href="/SageRelay/data/hc-action-disease.html">疾病防治（行动 11—15）</a></strong>：心脑血管、癌症、慢性呼吸、糖尿病、传染病及地方病。</li></ul><table tabindex="0"><thead><tr><th>#</th><th>行动</th><th>与本站的关系</th></tr></thead><tbody><tr><td>1</td><td>健康知识普及行动</td><td>本站的定位依据：把权威知识讲清楚</td></tr><tr><td>2</td><td>合理膳食行动</td><td><a href="/SageRelay/guides/hypertension-2023.html">食养指南词条</a>的直接上游政策</td></tr><tr><td>3</td><td>全民健身行动</td><td><a href="/SageRelay/data/physical-activity-2021.html">身体活动指南推荐量</a>的政策出口</td></tr><tr><td>4</td><td>控烟行动</td><td>各词条&quot;戒烟限酒&quot;条款的来源</td></tr><tr><td>5</td><td>心理健康促进行动</td><td>—</td></tr><tr><td>6</td><td>健康环境促进行动</td><td>—</td></tr><tr><td>7</td><td>妇幼健康促进行动</td><td>—</td></tr><tr><td>8</td><td>中小学健康促进行动</td><td><a href="/SageRelay/guides/student-meals-2017.html">学生餐营养指南</a>、<a href="/SageRelay/guides/child-obesity-2024.html">儿童肥胖</a>词条的政策背景</td></tr><tr><td>9</td><td>职业健康保护行动</td><td>—</td></tr><tr><td>10</td><td>老年健康促进行动</td><td><a href="/SageRelay/guides/sarcopenia-2026.html">肌少症</a>、<a href="/SageRelay/guides/osteoporosis-2026.html">骨质疏松</a>词条的政策背景</td></tr><tr><td>11</td><td>心脑血管疾病防治行动</td><td><a href="/SageRelay/guides/hypertension-2023.html">高血压</a>、<a href="/SageRelay/guides/stroke-2026.html">脑卒中</a>、<a href="/SageRelay/guides/hyperlipidemia-2023.html">高血脂</a></td></tr><tr><td>12</td><td>癌症防治行动</td><td>—</td></tr><tr><td>13</td><td>慢性呼吸系统疾病防治行动</td><td>—</td></tr><tr><td>14</td><td>糖尿病防治行动</td><td><a href="/SageRelay/guides/diabetes-2023.html">糖尿病食养指南</a></td></tr><tr><td>15</td><td>传染病及地方病防控行动</td><td>—</td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>健康中国行动推进委员会（国务院）</td></tr><tr><td>版本</td><td>2019—2030（现行）</td></tr><tr><td>发布时间</td><td>2019 年 7 月</td></tr><tr><td>原文直链</td><td><a href="https://www.gov.cn/xinwen/2019-07/15/content_5409694.htm" target="_blank" rel="noreferrer">gov.cn 全文</a></td></tr></tbody></table>',11)])])}const p=a(o,[["render",h]]);export{u as __pageData,p as default};
